input.command:
mkdir -p bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  default     = null
  description = "Name of the state bucket. Defaults to reports-tfstate-<account id> to be globally unique."
}
EOF
cat > main.tf <<'EOF'
provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

locals {
  bucket = coalesce(var.state_bucket_name, "reports-tfstate-${data.aws_caller_identity.current.account_id}")
}

resource "aws_s3_bucket" "state" {
  bucket = local.bucket

  # State holds secrets and is the only copy; make accidental deletion hard.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "tls_only" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.tls_only.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "init_command" {
  value = "terraform init -backend-config=\"bucket=${aws_s3_bucket.state.id}\" -backend-config=\"region=${var.region}\""
}
EOF
cd ..
cat >> versions.tf <<'EOF'
EOF
python3 - <<'EOF'
p='versions.tf'
s=open(p).read()
s=s.replace('  required_providers','''  # Bucket and region are supplied at init time (see README) because backend
  # blocks cannot use variables. The bucket is created by bootstrap/.
  backend "s3" {
    key          = "reports/terraform.tfstate"
    encrypt      = true
    use_lockfile = true
  }

  required_providers''',1)
open(p,'w').write(s)
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

State is stored in a versioned, encrypted, private S3 bucket (with S3 native locking via
`use_lockfile`, so no DynamoDB table is needed; requires Terraform >= 1.10). The bucket is
created by `bootstrap/`.

## One-time setup (one person)

```sh
cd bootstrap
terraform init
terraform apply
```

`bootstrap/` keeps its own state locally (it can't store state in a bucket that doesn't exist yet).
It rarely changes; keep `bootstrap/terraform.tfstate` somewhere safe, or re-import the bucket
if it is lost. The bucket has `prevent_destroy` set.

The bucket name defaults to `reports-tfstate-<account id>`; override with `-var state_bucket_name=...`.

## Migrating the existing local state (once)

From the laptop that holds the current `terraform.tfstate`, in the repo root:

```sh
terraform init -migrate-state \
  -backend-config="bucket=<bucket from bootstrap output>" \
  -backend-config="region=eu-north-1"
```

Answer `yes` to copy the local state to S3. Then verify `terraform plan` shows no changes and
delete the local `terraform.tfstate*` files.

## Everyday workflow (everyone)

```sh
terraform init \
  -backend-config="bucket=<bucket from bootstrap output>" \
  -backend-config="region=eu-north-1"
terraform plan
terraform apply
```

`terraform output -raw bootstrap`-style hints: run `terraform output init_command` inside
`bootstrap/` to print the exact init command.

## Access and security notes

- Each team member needs AWS credentials with `s3:ListBucket` on the bucket and
  `s3:GetObject`/`s3:PutObject`/`s3:DeleteObject` on `reports/*` (the lock file is
  `reports/terraform.tfstate.tflock`).
- The state contains the IAM access key secret for the uploader user in plain text. Restrict
  bucket access to the people who may read that secret.
- Never commit state files; `.gitignore` excludes them.
EOF
sed -i '/terraform output -raw bootstrap/,+1c\Run `terraform output init_command` inside `bootstrap/` to print the exact init command.' README.md
terraform fmt -recursive 2>&1; which terraform

